#!/usr/bin/env python3
# Some portions generated by Codex. Instrumented elapsed fields are never performance results.
import pathlib,re,json,sys
root=pathlib.Path(sys.argv[1]);out={};references={}
for p in sorted(root.glob('*.log')):
 text=p.read_text();rows=[]
 for l in text.splitlines():
  if l.startswith('audit '):
   r=dict(x.split('=',1) for x in l.split()[1:]);rows.append(r)
 assert rows,p
 key=p.stem.rsplit('-',1)[0]; arm=p.stem.rsplit('-',1)[1]
 checks={(r['rows'],r['checksum'],r['checksum2']) for r in rows};assert len(checks)==1,p
 value=next(iter(checks));assert references.setdefault(key,value)==value,p
 for l in text.splitlines():
  if l.startswith('budget '):
   d=dict(x.split('=',1) for x in l.split()[1:]);assert all(d[k]=='0' for k in ('migrated','spillCreated','spillDeleted','usedBefore','usedAfter')),p
 m=re.search(r'ownedDiagnostic run=0 supported=(true|false)(?: binds=(\d+) polls=(\d+) resets=(\d+))?',text)
 assert m,p
 counts=[int(x) for x in m.groups()[1:] if x is not None]
 if arm in ('C1','C1D') and 'probes' in key: assert len(counts)==3 and all(counts),p
 if arm in ('C0','C0D'): assert len(counts)==3 and not any(counts),p
 if key.startswith('warm'): assert len(rows)==21 and value==('100000','1899306305404719472','3694550068168048289'),p
 out[p.name]={'rowsChecksums':value,'ownershipSupported':m[1]=='true','bindsPollsResets':counts,'executions':len(rows)}
assert len(out)==26,len(out)
print(json.dumps({'note':'Untimed qualification only; do not compare elapsed fields','runs':out},indent=2))
